To solve this problem, we need to implement the rules of the Mini-Clay game. Here's a Python solution:

```python
class Candidate:
    def __init__(self, id, p, e, r, b):
        self.id = id
        self.p = p
        self.e = e
        self.r = r
        self.b = b
        self.score = p + e - r

    def __repr__(self):
        return f"@{self.id}[{self.p},{self.e},{self.r},{self.b}]"

def update_score(candidates, relation):
    s, t, w = relation.split(":")
    s_id = int(s[1:])
    t_id = int(t[1:])
    w = int(w)
    for candidate in candidates:
        if candidate.id == s_id and candidate.b == 0:
            candidate.score += w
            if candidate.id == t_id:
                candidate.score -= w

def solve_game(candidates, relations):
    for relation in relations:
        update_score(candidates, relation)

    eligible_candidates = [candidate for candidate in candidates if candidate.b == 0]
    eligible_candidates.sort(key=lambda x: (x.score, x.id))

    return
